// PlanBPerf Core: SRain.Update equivalent (exact, bit-identical float math).
// The original calls SViewClouds.GetCloudNeiPercentageCovered 16x per active cloud cell although the value depends only on
// (row, neighbour) and is constant between SRain.Reset calls. This file precomputes it once.
using System;

namespace PlanBPerf.Core
{
    public sealed class RainCache
    {
        public readonly int Nx, Ny;
        public readonly float[] Pct;   // [Ny*8]   Max(0.02f, GetCloudNeiPercentageCovered(j,k))
        public readonly int[] Nbr;     // [Nx*Ny*8] flat target cell (x*Ny+y) or -1 when the neighbour is Negative
        public readonly float[] Den;   // [Nx*Ny]  left-to-right float sum of Pct over valid neighbours (the original num3)
        public object WindRef, NeisRef; // identity of GWater.windAngle / GWater.cloudsNeis the cache was built from

        // pctMax: Max(0.02f, pct) per (j,k) = j*8+k, computed by the caller with the game's own function.
        // neiX/neiY: GWater.cloudsNeis flattened [(x*ny+y)*8+k]; x < 0 means Negative.
        public RainCache(int nx, int ny, float[] pctMax, int[] neiX, int[] neiY)
        {
            if (nx <= 0 || ny <= 0) throw new ArgumentException("clouds grid size");
            if (pctMax.Length != ny * 8) throw new ArgumentException("pct size");
            if (neiX.Length != nx * ny * 8 || neiY.Length != neiX.Length) throw new ArgumentException("neis size");
            Nx = nx; Ny = ny; Pct = pctMax;
            Nbr = new int[nx * ny * 8];
            Den = new float[nx * ny];
            for (int x = 0; x < nx; x++)
            {
                for (int j = 0; j < ny; j++)
                {
                    int cell = x * ny + j;
                    float num3 = 0f;
                    for (int k = 0; k < 8; k++)
                    {
                        int i = cell * 8 + k;
                        if (neiX[i] < 0)
                        {
                            Nbr[i] = -1;
                            continue;
                        }
                        if (neiX[i] >= nx || neiY[i] < 0 || neiY[i] >= ny) throw new IndexOutOfRangeException("cloud neighbour out of grid");
                        Nbr[i] = neiX[i] * ny + neiY[i];
                        num3 += pctMax[j * 8 + k];
                    }
                    Den[cell] = num3;
                }
            }
        }
    }

    public static unsafe class RainCore
    {
        // g: pinned cloudsGrid [nx,ny] row-major. item/count come from SMisc.GetSimuLoopIndexes (the game's own function).
        public static void Step(float* g, int gridLen, int item, int count, RainCache c)
        {
            int nx = c.Nx, ny = c.Ny;
            if (gridLen != nx * ny) throw new ArgumentException("grid length");
            int[] nbrArr = c.Nbr; float[] pctArr = c.Pct; float[] denArr = c.Den;
            fixed (int* nbr = nbrArr)
            fixed (float* pct = pctArr)
            fixed (float* den = denArr)
            {
                for (int i = 0; i < count; i++)
                {
                    int x = (item + i) % nx;
                    if (x < 0) throw new IndexOutOfRangeException("rain column");
                    int rowBase = x * ny;
                    for (int j = 0; j < ny; j++)
                    {
                        int idx = rowBase + j;
                        float cur = g[idx];
                        if (!(cur > 0f)) continue;
                        float half = 0.5f * cur;
                        g[idx] = g[idx] - half;
                        float q = half / den[idx];
                        int* nb = nbr + idx * 8;
                        float* pj = pct + j * 8;
                        for (int k = 0; k < 8; k++)
                        {
                            int n = nb[k];
                            if (n >= 0) g[n] = g[n] + q * pj[k];
                        }
                    }
                }
            }
        }
    }
}
