// PlanBPerf Core: SPoolModels.Update inner scan (same destroy set, same trimming; only the order of side-effect-free tests changes).
namespace PlanBPerf.Core
{
    public interface IPoolAccess
    {
        int Count { get; }
        int Counter(int i);          // PoolElement.counter
        bool NonNull(int i);         // go != null (UnityEngine.Object alive check)
        bool IsActive(int i);        // go.activeSelf (native call)
        void Destroy(int i);         // Object.Destroy(go)
        void RemoveRange(int start, int n);
    }

    public static class PoolScanCore
    {
        // Returns the number of Destroy calls issued.
        public static int Run<T>(ref T pool, float destroyLimit) where T : struct, IPoolAccess
        {
            int count = pool.Count;
            // original: num = index of the LAST element with go != null (0 when none)
            int num = 0;
            for (int j = count - 1; j >= 0; j--)
            {
                if (pool.NonNull(j)) { num = j; break; }
            }
            int destroyed = 0;
            // counters are creation indexes >= 0, so nothing is eligible while the limit is <= 0
            if (destroyLimit > 0f)
            {
                for (int j = 0; j < count; j++)
                {
                    if ((float)pool.Counter(j) < destroyLimit && pool.NonNull(j) && !pool.IsActive(j))
                    {
                        pool.Destroy(j);
                        destroyed++;
                    }
                }
            }
            if (num < count - 1)
            {
                pool.RemoveRange(num + 1, count - num - 1);
            }
            return destroyed;
        }
    }
}
