// PlanBPerf Core: SItems.Update10s_Planet scan. Skips empty hexes with a byte read; non-empty hexes go to the
// original body (host.Process) in the same order.
using System;

namespace PlanBPerf.Core
{
    public interface IScan10sHost
    {
        // original body for one hex: coords = IntToCoord(idx); content = contentId[coords]; if (content != 0) {...virtual Update10s_Planet}
        void Process(uint idx);
    }

    public static unsafe class Scan10sCore
    {
        public static void Run<T>(ref T host, uint[] indexesRandom, byte* content, long contentLen, int item, int count, int nbHexes) where T : struct, IScan10sHost
        {
            for (int i = 0; i < count; i++)
            {
                int n = (item + i) % nbHexes;
                uint idx = indexesRandom[n];
                if (idx < (ulong)contentLen && content[idx] == 0) continue;
                host.Process(idx);
            }
        }
    }
}
