// PlanBPerf Core: SItems.Update30s_Planet. O2 census + filtered-water census + grass update, same order, same float accumulation order.
using System;

namespace PlanBPerf.Core
{
    public interface ICensusHost
    {
        // forest at content id (forestById[content] != null)?  Used for the O2 census.
        bool IsForest(int contentId);
        // forest.IsAliveAndVisible(IntToCoord(idx)) for a forest content id
        bool ForestAliveAndVisible(int contentId, uint idx);
        float ForestO2(int contentId);
        // itemGrass.id and itemGrass.nbTreeO2, GPlanet.o2_nbTreePerPlankton, GWater.waterDepthMin
        int GrassId { get; }
        float GrassO2 { get; }
        float PlanktonO2 { get; }
        float WaterDepthMin { get; }
        // the num==0 block: receives the counters BEFORE they are reset (the block then resets them itself in Core)
        void OnWrap(float o2, int filtered);
        // is groundById[groundId] a CItem_GroundGrass?  (GetGround(coords) as CItem_GroundGrass != null)
        bool IsGrass(int groundId);
        void GrassUpdate(int groundId, uint idx);   // grass.Update30s_Planet(IntToCoord(idx), 30f)
    }

    public static unsafe class Census30sCore
    {
        // o2 / filtered are the SItems fields (nbTreeO2counter / nbFilteredWater); the updated values are returned via ref.
        public static void Run<T>(ref T host, ref float o2, ref int filtered,
            uint[] indexesRandom, byte* contentId, byte* groundId, float* water, float* plankton, float* filteredWater, long len,
            int item, int count, int nbHexes) where T : struct, ICensusHost
        {
            int grassId = host.GrassId;
            float grassO2 = host.GrassO2;
            float planktonO2 = host.PlanktonO2;
            float waterMin = host.WaterDepthMin;
            for (int i = 0; i < count; i++)
            {
                int num = (item + i) % nbHexes;
                uint idx = indexesRandom[num];
                if (idx >= (ulong)len) throw new IndexOutOfRangeException("hex index");

                // Increase02Counter
                if (!(o2 < 0f))
                {
                    int cid = contentId[idx];
                    if (cid != 0 && host.IsForest(cid) && host.ForestAliveAndVisible(cid, idx))
                    {
                        o2 += host.ForestO2(cid);
                    }
                    else if (groundId[idx] == grassId)
                    {
                        o2 += grassO2;
                    }
                    else if (water[idx] > waterMin && plankton[idx] > 1f)
                    {
                        o2 += planktonO2;
                    }
                }
                // IncreaseFilteredWaterCounter
                if (filtered >= 0 && water[idx] > waterMin && (plankton[idx] > 1f || filteredWater[idx] > 1f))
                {
                    filtered++;
                }
                if (num == 0)
                {
                    host.OnWrap(o2, filtered);
                    o2 = 0f;
                    filtered = 0;
                }
                int gid = groundId[idx];
                if (gid > 0 && host.IsGrass(gid))
                {
                    host.GrassUpdate(gid, idx);
                }
            }
        }
    }
}
