// PlanBPerf Core: fast fill of a 2D int array with -1 (the _waterVertexIndex reset of SViewWater.UpdateWaterMesh_ResetMesh).
using System;

namespace PlanBPerf.Core
{
    public static class FillCore
    {
        // Equivalent to: for i<GetLength(0) for j<GetLength(1) a[i,j] = value;   (memcpy doubling instead of 2.4M bounds-checked stores)
        public static void FillAll(int[,] a, int value)
        {
            int n = a.Length;
            if (n == 0) return;
            const int seedLen = 4096;
            int[] seed = new int[Math.Min(seedLen, n)];
            for (int i = 0; i < seed.Length; i++) seed[i] = value;
            Array.Copy(seed, 0, a, 0, seed.Length);   // multi-dim arrays are copied in row-major linear order
            int filled = seed.Length;
            while (filled < n)
            {
                int c = Math.Min(filled, n - filled);
                Array.Copy(a, 0, a, filled, c);
                filled += c;
            }
        }
    }
}
