// PlanBPerf Core: the index arithmetic of the native water wrapper (Dll_UpdateWaterSimu), verified against the DLL disassembly:
// start = trunc(last * N / 0.30000001192092896) % N  (cvttsd2si truncation, signed 64-bit modulo).
using System;

namespace PlanBPerf.Core
{
    public static class LoopIndexMath
    {
        public const double Period = 0.30000001192092896;   // (double)0.3f

        public static int Start(double last, int n)
        {
            if (n == 0) return 0;
            long v = Trunc(last * n / Period);
            return (int)(v % n);
        }

        // cvttsd2si semantics: out-of-range / NaN gives 0x8000000000000000
        public static long Trunc(double d)
        {
            if (double.IsNaN(d) || d >= 9.2233720368547758E+18 || d < -9.2233720368547758E+18) return long.MinValue;
            return (long)d;
        }

        // same bookkeeping as SWater.UpdateWaterSimu_1s: result = num < _lastSimuI
        public static bool JustDone(int start, int lastSimuI) { return start < lastSimuI; }
    }
}
