// PlanBPerf Core: CPoolTransports<T>.DeactivateHiddenModels with a per-model shadow so SetActive(false) is only issued when the model
// may be active. A model is known inactive iff we deactivated it at frame F and it has not been displayed since (lastFrameDisplayed < F).
namespace PlanBPerf.Core
{
    public interface IPoolModels
    {
        int Count { get; }
        int LastFrameDisplayed(int i);
        object Model(int i);          // identity of the pooled model object
        void SetInactive(int i);      // transform.gameObject.SetActive(false)
    }

    public sealed class DeactivateShadow
    {
        public object[] Owner = new object[0];
        public int[] DeactFrame = new int[0];     // frame at which we issued SetActive(false); 0 = unknown

        public void Ensure(int n)
        {
            if (Owner.Length >= n) return;
            int cap = System.Math.Max(n, Owner.Length * 2);
            System.Array.Resize(ref Owner, cap);
            System.Array.Resize(ref DeactFrame, cap);
        }
    }

    public static class DeactivateCore
    {
        // Returns the number of SetActive(false) calls issued.
        public static int Run<T>(ref T pool, DeactivateShadow sh, int frameCount) where T : struct, IPoolModels
        {
            int n = pool.Count;
            sh.Ensure(n);
            int calls = 0;
            for (int i = 0; i < n; i++)
            {
                int last = pool.LastFrameDisplayed(i);
                if (last >= frameCount) continue;
                object m = pool.Model(i);
                if (!ReferenceEquals(sh.Owner[i], m))
                {
                    sh.Owner[i] = m;
                    sh.DeactFrame[i] = 0;
                }
                int df = sh.DeactFrame[i];
