// Publicize: writes a COMPILE-ONLY copy of Assembly-CSharp.dll with every type and member public.
// The copy is never shipped; at runtime Mono resolves the plugin's references against the real (non-public) members.
//   usage: Publicize <in.dll> <out.dll>
using System;
using System.IO;
using Mono.Cecil;

static class Program
{
    static void Main(string[] args)
    {
        var asm = AssemblyDefinition.ReadAssembly(args[0], new ReaderParameters { ReadWrite = false });
        int n = 0;
        foreach (var type in asm.MainModule.Types) n += Pub(type);
        asm.Write(args[1]);
        Console.WriteLine("publicized members: " + n + " -> " + args[1]);
    }

    static int Pub(TypeDefinition t)
    {
        int n = 0;
        if (t.IsNested) { t.IsNestedPublic = true; } else { t.IsPublic = true; }
        foreach (var m in t.Methods) { if (!m.IsPublic) { m.IsPublic = true; n++; } }
        foreach (var f in t.Fields) { if (!f.IsPublic) { f.IsPublic = true; n++; } }
        foreach (var nt in t.NestedTypes) n += Pub(nt);
        return n;
    }
}
