// PlanBPerf: per-patch runtime guard. An exception inside a patch logs once and turns that patch off (original code runs again from the next call).
using System;
using System.Collections.Generic;
using UnityEngine;

namespace PlanBPerf
{
    internal enum P
    {
        RainFast, PoolScan, SimLavaFireScan, Update10sScan, Update30sCensus, ViewWorldScan, WaterMeshFast,
        DeactivateHiddenCache, PtrCache, UnloadGate, ForcedGcOff, Diagnostics, AsyncSim, OmpThreads,
        Count
    }

    internal sealed class SkipException : Exception
    {
        public SkipException(string m) : base(m) { }
    }

    internal static class Guard
    {
        internal static readonly bool[] On = new bool[(int)P.Count];          // patch is applied AND not disabled at runtime
        internal static readonly string[] State = new string[(int)P.Count];   // off | active | SKIP: reason | DISABLED: reason
        private static readonly HashSet<int> _logged = new HashSet<int>();

        internal static void Log(string msg)
        {
            Debug.Log("[PlanBPerf] " + msg);
        }

        internal static void LogWarn(string msg)
        {
            Debug.LogWarning("[PlanBPerf] " + msg);
        }

        internal static void Skip(P id, string reason)
        {
            On[(int)id] = false;
            State[(int)id] = "SKIP: " + reason;
            Log("SKIP " + id + ": " + reason);
        }

        internal static void Disable(P id, Exception e)
        {
            On[(int)id] = false;
            State[(int)id] = "DISABLED: " + e.GetType().Name;
            if (_logged.Add((int)id))
            {
                LogWarn("DISABLED " + id + " after exception, original code runs from now on: " + e);
            }
        }

        internal static string Keys(bool wantOn)
        {
            var sb = new System.Text.StringBuilder();
            for (int i = 0; i < (int)P.Count; i++)
            {
                bool isOn = State[i] == "active";
                bool isDisabled = State[i] != null && State[i].StartsWith("DISABLED");
                if (wantOn ? isOn : isDisabled)
                {
                    if (sb.Length > 0) sb.Append(',');
                    sb.Append((P)i);
                }
            }
            return sb.Length == 0 ? "-" : sb.ToString();
        }
    }

