        private static bool Run()
        {
            SDebug.FPS_Start("- SRain.Update()");
            try
            {
                int2 size = GWater.cloudsGridSize;
                var li = SMisc.GetSimuLoopIndexes(GMain.simuPlanetTime_LastFrame, GMain.simuPlanetTime, 1f, size.x);
                RainCache c = GetCache(size);
                float[,] grid = GWater.cloudsGrid;
                if (grid.GetLength(0) != size.x || grid.GetLength(1) != size.y) throw new InvalidOperationException("cloudsGrid dims");
                fixed (float* g = &grid[0, 0])
                {
                    RainCore.Step(g, grid.Length, li.Item1, li.Item2, c);
                }
            }
            finally
            {
                SDebug.FPS_End();
            }
            return true;
        }

        private static RainCache GetCache(int2 size)
        {
            RainCache c = _cache;
            if (c != null && c.Nx == size.x && c.Ny == size.y && ReferenceEquals(c.WindRef, GWater.windAngle) && ReferenceEquals(c.NeisRef, GWater.cloudsNeis))
            {
                return c;
            }
            int nx = size.x, ny = size.y;
            SViewClouds vc = SSingleton<SViewClouds>.Inst;
            float[] pct = new float[ny * 8];
            for (int j = 0; j < ny; j++)
            {
                for (int k = 0; k < 8; k++)
                {
                    pct[j * 8 + k] = Mathf.Max(0.02f, vc.GetCloudNeiPercentageCovered(j, k));
                }
            }
            int2[,,] neis = GWater.cloudsNeis;
            if (neis.GetLength(0) != nx || neis.GetLength(1) != ny || neis.GetLength(2) != 8) throw new InvalidOperationException("cloudsNeis dims");
            int[] nxs = new int[nx * ny * 8];
            int[] nys = new int[nx * ny * 8];
            for (int x = 0; x < nx; x++)
            {
                for (int j = 0; j < ny; j++)
                {
                    for (int k = 0; k < 8; k++)
                    {
                        int2 v = neis[x, j, k];
                        int i = (x * ny + j) * 8 + k;
                        nxs[i] = v.Negative ? -1 : v.x;
                        nys[i] = v.y;
                    }
                }
            }
            c = new RainCache(nx, ny, pct, nxs, nys);
            c.WindRef = GWater.windAngle;
            c.NeisRef = GWater.cloudsNeis;
            _cache = c;
            return c;
        }
