// PlanBPerf Core: one long-lived worker that runs the three native sim calls strictly in order (water -> smooth currents -> pollution),
// with a join that always waits for completion. No UnityEngine, no game types: the natives are injected (IWork) so the ordering,
// join and exception semantics are unit-testable without the game.
using System;
using System.Diagnostics;
using System.Threading;

namespace PlanBPerf.Core
{
    public interface IAsyncWork
    {
        void RunWater();
        void RunSmooth();
        void RunPollution();
    }

    public sealed class AsyncSimCore : IDisposable
    {
        private readonly IAsyncWork _work;
        private readonly object _gate = new object();
        private readonly Thread _thread;
        private bool _hasJob, _jobDone = true, _quit, _withSmooth;
        private Exception _error;
        private volatile bool _inFlight;

        public AsyncSimCore(IAsyncWork work, string threadName)
        {
            _work = work;
            _thread = new Thread(Loop) { IsBackground = true, Name = threadName };
            _thread.Start();
        }

        public bool InFlight { get { return _inFlight; } }
        public int WorkerThreadId { get { return _thread.ManagedThreadId; } }

        public void Enqueue(bool withSmoothAndPollution)
        {
            lock (_gate)
            {
                if (!_jobDone) throw new InvalidOperationException("previous job not joined");
                _jobDone = false;
                _hasJob = true;
                _withSmooth = withSmoothAndPollution;
                _error = null;
                _inFlight = true;
                Monitor.PulseAll(_gate);
            }
        }

        // Blocks until the worker finished the current job (no timeout that proceeds). Returns the worker's exception or null.
        public Exception Join(out double waitedMs, Action<double> slowWaitLog = null)
        {
            Stopwatch sw = Stopwatch.StartNew();
            bool logged = false;
            lock (_gate)
            {
                while (!_jobDone)
                {
                    Monitor.Wait(_gate, 1000);
                    if (!_jobDone && !logged && sw.Elapsed.TotalSeconds > 1.0)
                    {
                        logged = true;
                        if (slowWaitLog != null) slowWaitLog(sw.Elapsed.TotalMilliseconds);
                    }
                }
                _inFlight = false;
                waitedMs = sw.Elapsed.TotalMilliseconds;
                return _error;
            }
        }

        private void Loop()
        {
            while (true)
            {
                bool smooth;
                lock (_gate)
                {
                    while (!_hasJob && !_quit) Monitor.Wait(_gate);
                    if (_quit) return;
                    _hasJob = false;
                    smooth = _withSmooth;
                }
                Exception err = null;
                try
                {
                    _work.RunWater();
                    if (smooth)
                    {
                        _work.RunSmooth();
                        _work.RunPollution();
                    }
                }
                catch (Exception e)
                {
                    err = e;
                }
                lock (_gate)
                {
                    _error = err;
                    _jobDone = true;
                    Monitor.PulseAll(_gate);
                }
            }
        }

        public void Dispose()
        {
            lock (_gate)
            {
                _quit = true;
                Monitor.PulseAll(_gate);
            }
        }
    }
}
