                Try(P.ViewWorldScan, h, ViewWorldPatch.Apply);
                Try(P.WaterMeshFast, h, WaterMeshPatch.Apply);
                Try(P.DeactivateHiddenCache, h, DeactivateHiddenPatch.Apply);
                TrySWater(h);
                Try(P.UnloadGate, h, UnloadGate.Apply);
