                Try(P.Diagnostics, h, DiagnosticsPatch.Apply);
                if (Cfg.OmpThreads.Value > 0) { Guard.On[(int)P.OmpThreads] = false; TryRaw(P.OmpThreads, h, OmpThreadsPatch.Apply); } else Guard.State[(int)P.OmpThreads] = "off";
