            }
        }

        private static string SkippedList()
        {
            var sb = new System.Text.StringBuilder();
            for (int i = 0; i < (int)P.Count; i++)
            {
                string s = Guard.State[i];
                if (s != null && s != "active" && s != "off") sb.Append(((P)i).ToString()).Append('(').Append(s).Append(") ");
