                if (!handled) { res.Bad("seed=" + seed + " patch did not handle the call"); break; }
                res.Runs++;
                if (poolA.ModelCount != poolB.ModelCount) { res.Bad("seed=" + seed + " model count differs"); break; }
                for (int m = 0; m < poolA.ModelCount; m++)
                {
                    bool aa = poolA.ModelAt(m).transform.gameObject.activeSelf, bb = poolB.ModelAt(m).transform.gameObject.activeSelf;
                    if (aa != bb) { res.Bad("seed=" + seed + " frame=" + frame + " model " + m + " active " + aa + " vs " + bb); frame = 999; break; }
                }
            }
            for (int m = 0; m < poolA.ModelCount && res.Mismatches == 0; m++)
            {
                callsA += poolA.ModelAt(m).transform.gameObject.SetActiveCalls;
                callsB += poolB.ModelAt(m).transform.gameObject.SetActiveCalls;
            }
        }
        if (res.Mismatches == 0 && callsB >= callsA) res.Bad("SetActive calls not reduced: orig=" + callsA + " new=" + callsB);
